INSERT OR IGNORE INTO news_posts (id, slug, title, excerpt, content_html, seo_title, meta_description, focus_keyword, canonical_url, og_title, og_description, cover_alt, status, published_at, updated_by) VALUES ('jc-guia-20261008-1', 'como-encontrar-abogado-chile', 'Cómo encontrar un abogado en Chile: criterios para elegir', 'Aprende qué revisar al buscar un abogado en Chile: especialidad, experiencia, forma de trabajo y propuesta. Prepara una elección informada con JurisConecta.', '<p>Encontrar un abogado en Chile no consiste únicamente en buscar un nombre o elegir la primera respuesta. Conviene entender qué ayuda necesitas, qué experiencia requiere tu situación y cómo se organizará la relación profesional. Esta guía ofrece una lista práctica para preparar esa elección sin prometer resultados ni reemplazar una consulta jurídica.</p>
<h2>Define el problema antes de buscar</h2><p>Escribe una explicación breve: qué ocurrió, quiénes participan, dónde sucedió y qué necesitas resolver. Distingue los hechos que conoces de tus interpretaciones. Si recibiste una notificación o tienes una fecha importante, indícalo al profesional para que evalúe la urgencia. No esperes una respuesta de una plataforma cuando la situación requiera atención inmediata.</p>
<h2>Busca una especialidad relacionada con tu situación</h2><p>Las materias de familia, laboral, civil y penal requieren enfoques diferentes. Pregunta si el abogado trabaja habitualmente con situaciones similares y qué información necesita para evaluar la tuya. La experiencia relevante se puede explicar sin revelar datos privados de otros clientes. Evita basar la decisión solo en una foto, un cargo o una promesa comercial.</p>
<h2>Revisa cómo se verifican los antecedentes</h2><p>Pregunta por el título profesional, la identidad y el procedimiento de verificación. Una aprobación dentro de una plataforma no garantiza el resultado de una causa. En el piloto de JurisConecta, las postulaciones profesionales requieren revisión manual antes de acceder al flujo habilitado para abogados aprobados. Esa revisión no debe confundirse con una certificación de especialidad ni con un respaldo del Poder Judicial.</p>
<h2>Aclara el servicio y los honorarios</h2><ul><li>¿Qué tareas incluye la propuesta y cuáles quedan fuera?</li><li>¿Quién atenderá tu consulta y cómo te comunicarás?</li><li>¿Cómo se informarán los avances y con qué frecuencia?</li><li>¿Qué gastos pueden existir además de los honorarios?</li><li>¿Qué ocurre si necesitas terminar la relación profesional?</li></ul>
<p>Solicita estas condiciones por escrito. Un monto aislado no permite comparar dos servicios con alcances diferentes. También conviene preguntar qué información es preliminar y qué requiere estudiar documentos.</p>
<h2>Decide con información, sin garantías de resultado</h2><p>Una explicación comprensible, un alcance claro y expectativas realistas son más útiles que una promesa de éxito. Revisa nuestra guía para <a href="/noticias/comparar-propuestas-abogados-honorarios/">comparar propuestas de abogados</a> antes de tomar una decisión.</p><p>En JurisConecta puedes <a href="/registro/">crear una cuenta de cliente</a> y preparar tu caso. El sitio está en fase piloto: usa <a href="/soporte/">soporte</a> si necesitas conocer sus límites y no publiques documentos ni datos sensibles innecesarios.</p>', 'Cómo encontrar un abogado en Chile | JurisConecta', 'Aprende qué revisar al buscar un abogado en Chile: especialidad, experiencia, forma de trabajo y propuesta. Prepara una elección informada con JurisConecta.', 'encontrar abogado en Chile', 'https://jurisconecta.cl/noticias/como-encontrar-abogado-chile/', 'Cómo encontrar un abogado en Chile | JurisConecta', 'Aprende qué revisar al buscar un abogado en Chile: especialidad, experiencia, forma de trabajo y propuesta. Prepara una elección informada con JurisConecta.', 'Cómo encontrar un abogado en Chile: criterios para elegir', 'published', CURRENT_TIMESTAMP, 'gprecabarren');
INSERT OR IGNORE INTO news_posts (id, slug, title, excerpt, content_html, seo_title, meta_description, focus_keyword, canonical_url, og_title, og_description, cover_alt, status, published_at, updated_by) VALUES ('jc-guia-20261008-2', 'preparar-primera-consulta-abogado', 'Cómo preparar tu primera consulta con un abogado', 'Organiza los hechos, documentos y preguntas de tu primera consulta con un abogado. Comparte solo lo necesario y prepara tu caso con mayor claridad.', '<p>La primera consulta con un abogado es una oportunidad para explicar tu situación y entender los siguientes pasos posibles. Una preparación sencilla ayuda a aprovecharla: ordenar los hechos, identificar las dudas y reunir la información relevante. No necesitas convertir tu relato en un escrito jurídico ni conocer de antemano todas las respuestas.</p>
<h2>Prepara una cronología breve</h2><p>Anota los acontecimientos en orden, con las fechas que conozcas. Si una fecha es aproximada, acláralo. Describe quién participó y qué ocurrió, separando los hechos de las opiniones. Lleva una versión breve para comenzar la conversación y conserva el detalle por si el profesional lo necesita.</p><p>Incluye las comunicaciones o notificaciones recibidas y cualquier plazo que figure en ellas. El abogado debe revisar su alcance; esta guía no calcula vencimientos ni determina qué acción corresponde a tu situación.</p>
<h2>Organiza los documentos sin publicarlos de más</h2><p>Haz una lista de los antecedentes que tienes: contratos, comunicaciones, comprobantes o resoluciones, según corresponda. Conserva los originales y no alteres archivos. Antes de enviarlos, pregunta qué necesita revisar el profesional y cuál es el medio adecuado.</p><p>En un resumen inicial de una plataforma evita incluir RUT, datos de menores, información de salud, claves, números bancarios o documentos completos. No supongas que todo formulario es una vía para entregar antecedentes confidenciales. En el piloto de JurisConecta no existe un expediente documental judicial ni una sincronización con tribunales.</p>
<h2>Define qué quieres preguntar</h2><ul><li>¿Qué información falta para evaluar el caso?</li><li>¿Qué alternativas se podrían analizar?</li><li>¿Qué tareas incluye la consulta y qué requiere un encargo adicional?</li><li>¿Cómo se informan los honorarios, gastos y condiciones?</li><li>¿Cuál es el siguiente paso y quién debe realizarlo?</li></ul><p>También puedes pedir una explicación en lenguaje claro. Si algo no se entiende, conviene aclararlo antes de aceptar una propuesta.</p>
<h2>Publica un resumen útil, no toda tu historia privada</h2><p>Para preparar un caso en JurisConecta, selecciona la materia y ubicación, explica lo esencial y revisa el resumen antes de enviarlo. La cuenta del cliente permite consultar el estado de la plataforma y las propuestas recibidas. No reemplaza la comunicación directa con el abogado ni acredita una actuación judicial.</p>
<h2>Revisa lo acordado al terminar</h2><p>Confirma qué información debes reunir y qué condiciones quedaron pendientes. Guarda las instrucciones y pide que el alcance de un eventual servicio quede por escrito. Puedes continuar con nuestra guía sobre <a href="/noticias/como-encontrar-abogado-chile/">cómo encontrar un abogado en Chile</a> o revisar <a href="/soporte/">las preguntas frecuentes de JurisConecta</a>.</p>', 'Primera consulta con un abogado: qué preparar | JurisConecta', 'Organiza los hechos, documentos y preguntas de tu primera consulta con un abogado. Comparte solo lo necesario y prepara tu caso con mayor claridad.', 'primera consulta con un abogado', 'https://jurisconecta.cl/noticias/preparar-primera-consulta-abogado/', 'Primera consulta con un abogado: qué preparar | JurisConecta', 'Organiza los hechos, documentos y preguntas de tu primera consulta con un abogado. Comparte solo lo necesario y prepara tu caso con mayor claridad.', 'Cómo preparar tu primera consulta con un abogado', 'published', CURRENT_TIMESTAMP, 'gprecabarren');
INSERT OR IGNORE INTO news_posts (id, slug, title, excerpt, content_html, seo_title, meta_description, focus_keyword, canonical_url, og_title, og_description, cover_alt, status, published_at, updated_by) VALUES ('jc-guia-20261008-3', 'comparar-propuestas-abogados-honorarios', 'Cómo comparar propuestas de abogados y sus honorarios', 'Compara propuestas de abogados por alcance, honorarios, gastos y comunicación. Conoce qué revisar antes de aceptar una propuesta dentro de JurisConecta.', '<p>Dos propuestas de abogados pueden parecer similares y, aun así, contemplar trabajos distintos. Compararlas únicamente por el precio puede llevar a una decisión poco informada. La clave es revisar el alcance, las condiciones económicas y la forma de comunicación, dejando por escrito las dudas antes de aceptar un servicio.</p>
<h2>Compara el mismo alcance</h2><p>Identifica qué incluye cada propuesta: una consulta, una revisión de antecedentes, una negociación o una representación, según lo que se haya ofrecido. Pregunta cuáles son los entregables, qué tareas no están incluidas y qué circunstancias podrían exigir un nuevo acuerdo. Una propuesta preliminar puede necesitar ajustes después de estudiar documentos.</p>
<h2>Distingue honorarios, gastos y condiciones</h2><p>Los honorarios corresponden al trabajo profesional acordado. Puede haber gastos adicionales que deben aclararse antes de contratar. Pide que se indique si el monto incluye todos los conceptos ofrecidos, cómo se paga y qué condiciones permiten modificarlo. Esta guía no establece tarifas ni recomienda un precio para un caso particular.</p><ul><li>Monto y forma de cálculo explicados con claridad.</li><li>Etapas de pago y condiciones de cada una.</li><li>Gastos incluidos y gastos que podrían surgir.</li><li>Alcance de revisiones o actuaciones adicionales.</li><li>Condiciones de término y rendición de gastos, si corresponde.</li></ul>
<h2>Evalúa la comunicación y las expectativas</h2><p>Pregunta quién será tu contacto, por qué medio se informarán los avances y cómo resolverás nuevas dudas. Una buena explicación debe distinguir lo que ya se conoce de aquello que necesita evaluación. Los tiempos de un procedimiento y sus resultados no deben presentarse como garantías.</p>
<h2>Cómo funciona la comparación en JurisConecta</h2><p>En el piloto, el cliente puede revisar las propuestas asociadas a su caso desde su cuenta, comparar sus condiciones y aceptar o descartar una. El flujo contempla hasta tres propuestas por caso. La aceptación dentro de la plataforma habilita la siguiente etapa de contacto para el abogado seleccionado; no significa que una causa haya comenzado en tribunales.</p><p>El contacto no debe desbloquearse antes de esa aceptación. Los créditos profesionales son de prueba y JurisConecta no procesa cobros ni pagos de honorarios. El acuerdo profesional y cualquier obligación económica deben aclararse directamente entre las partes, mediante condiciones adecuadas al servicio.</p>
<h2>Antes de decidir</h2><p>Revisa que entiendes el alcance y solicita aclaraciones por escrito. Conserva la propuesta aceptada y la documentación del acuerdo. Si tienes una dificultad técnica con la plataforma, utiliza <a href="/soporte/">soporte y tickets</a>; ese canal no sustituye una consulta jurídica. Para ordenar tus antecedentes, revisa <a href="/noticias/preparar-primera-consulta-abogado/">cómo preparar la primera consulta</a>.</p>', 'Comparar propuestas y honorarios de abogados | JurisConecta', 'Compara propuestas de abogados por alcance, honorarios, gastos y comunicación. Conoce qué revisar antes de aceptar una propuesta dentro de JurisConecta.', 'comparar propuestas de abogados', 'https://jurisconecta.cl/noticias/comparar-propuestas-abogados-honorarios/', 'Comparar propuestas y honorarios de abogados | JurisConecta', 'Compara propuestas de abogados por alcance, honorarios, gastos y comunicación. Conoce qué revisar antes de aceptar una propuesta dentro de JurisConecta.', 'Cómo comparar propuestas de abogados y sus honorarios', 'published', CURRENT_TIMESTAMP, 'gprecabarren');
INSERT OR IGNORE INTO news_posts (id, slug, title, excerpt, content_html, seo_title, meta_description, focus_keyword, canonical_url, og_title, og_description, cover_alt, status, published_at, updated_by) VALUES ('jc-guia-20261008-4', 'seguimiento-caso-panel-cliente', 'Seguimiento de tu caso: qué muestra el panel de cliente', 'Conoce el panel de cliente de JurisConecta: estado del caso, propuestas y soporte. Distingue los hitos de la plataforma del avance judicial de una causa.', '<p>Enviar una consulta legal y no saber qué ocurrió después puede generar incertidumbre. JurisConecta incorpora una cuenta de cliente para consultar el estado de los casos publicados y las propuestas asociadas. Es un seguimiento del proceso dentro de la plataforma, no una conexión automática con tribunales ni una fuente de información judicial en tiempo real.</p>
<h2>Tu cuenta reúne los casos publicados</h2><p>Al ingresar, el cliente puede revisar sus casos y acceder al detalle de cada uno. El panel organiza los estados y datos de actividad disponibles para que no dependas únicamente de un correo. Es importante comprobar que el resumen sea claro y no contenga información privada que no sea necesaria para la evaluación inicial.</p>
<h2>Qué significan los indicadores</h2><p>Las vistas y propuestas son indicadores de actividad de la plataforma. No acreditan que un abogado haya estudiado todos los antecedentes ni que se haya presentado una acción. Las etapas permiten orientarte en el recorrido: publicación, revisión de propuestas, decisión y cierre del caso dentro del sitio.</p><p>Si una causa tiene actuaciones judiciales, plazos o resoluciones, su interpretación debe revisarse con el abogado responsable. El piloto todavía no incorpora hitos jurídicos ingresados por el profesional, adjuntos seguros ni sincronización de expedientes.</p>
<h2>Revisa las propuestas antes de aceptar</h2><p>El detalle del caso permite revisar las propuestas recibidas y tomar una decisión. Compara el servicio y sus condiciones, pide aclaraciones cuando corresponda y no interpretes la aceptación como una garantía de resultado. Nuestra guía para <a href="/noticias/comparar-propuestas-abogados-honorarios/">comparar propuestas y honorarios</a> explica los aspectos que conviene revisar.</p>
<h2>Notificaciones y soporte tienen alcances distintos</h2><p>Los avisos del piloto son internos. No existe envío automático de correos o WhatsApp para todas las acciones. Revisa tu panel para ver la información disponible. Si encuentras un error técnico, puedes crear un ticket autenticado y consultar sus respuestas desde soporte o tu cuenta.</p><p>Al abrir un ticket, describe el problema de funcionamiento, la pantalla y el resultado esperado. No adjuntes información confidencial de una causa ni contraseñas. Un ticket técnico no es una solicitud de asesoría jurídica.</p>
<h2>Cuida el acceso a tu cuenta</h2><p>Consulta las sesiones activas y cierra las de dispositivos que ya no uses. Las ubicaciones mostradas son aproximadas y pueden variar con una VPN. El acceso con Google, cuando está habilitado, mantiene los mismos permisos del tipo de cuenta: no convierte a un cliente en abogado ni en administrador.</p><p>Puedes <a href="/ingresar/">iniciar sesión</a> para revisar tus casos o consultar <a href="/soporte/">las preguntas frecuentes</a>. JurisConecta continúa en fase piloto; el seguimiento judicial real es parte del trabajo pendiente y no una función ya disponible.</p>', 'Seguimiento de casos en el panel de cliente | JurisConecta', 'Conoce el panel de cliente de JurisConecta: estado del caso, propuestas y soporte. Distingue los hitos de la plataforma del avance judicial de una causa.', 'seguimiento de casos', 'https://jurisconecta.cl/noticias/seguimiento-caso-panel-cliente/', 'Seguimiento de casos en el panel de cliente | JurisConecta', 'Conoce el panel de cliente de JurisConecta: estado del caso, propuestas y soporte. Distingue los hitos de la plataforma del avance judicial de una causa.', 'Seguimiento de tu caso: qué muestra el panel de cliente', 'published', CURRENT_TIMESTAMP, 'gprecabarren');
